223	/**
224	* This function retrieves the reports given a certain group id as defined in /reports/admin/defaults.php
225	* in the associative array $ReportGroups[]. It will fetch the reports belonging solely to the group
226	* specified to create a list of links for insertion into a table to choose a report. Two table sections will
227	* be generated, one for standard reports and the other for custom reports.
228	 */
229	function GetRptLinks($GroupID) {
230		global $RootPath;
231		if (!isset($_SESSION['FormGroups'])) {
232			$_SESSION['FormGroups'] = array('gl:chk' => __('Bank Checks'), // Bank checks grouped with the gl report group
233			'ar:col' => __('Collection Letters'), 'ar:cust' => __('Customer Statements'), 'gl:deps' => __('Bank Deposit Slips'), 'ar:inv' => __('Invoices and Packing Slips'), 'ar:lblc' => __('Labels - Customer'), 'prch:lblv' => __('Labels - Vendor'), 'prch:po' => __('Purchase Orders'), 'ord:quot' => __('Customer Quotes'), 'ar:rcpt' => __('Sales Receipts'), 'ord:so' => __('Sales Orders'), 'misc:misc' => __('Miscellaneous')); // do not delete misc category
234	
235		}
236		if (isset($_SESSION['ReportList'][$GroupID])) {
237			$GroupID = $_SESSION['ReportList'][$GroupID];
238		}
239		$Title = array(__('Custom Reports'), __('Standard Reports and Forms'));
240	
241		if (!isset($_SESSION['ReportList'])) {
242			$SQL = "SELECT id,
243							reporttype,
244							defaultreport,
245							groupname,
246							reportname
247						FROM reports
248						ORDER BY groupname,
249								reportname";
250			$Result = DB_query($SQL, '', '', false, true);
251			$_SESSION['ReportList'] = array();
252			while ($Temp = DB_fetch_assoc($Result)) {
253				$_SESSION['ReportList'][] = $Temp;
254			}
255		}
256		$RptLinks = '';
257		for ($Def = 1;$Def >= 0;$Def--) {
258			$RptLinks.= '<li class="CustomMenuList">';
259			$RptLinks.= '<b>' . $Title[$Def] . '</b>';
260			$RptLinks.= '</li>';
261			$NoEntries = true;
262			if (isset($_SESSION['ReportList']['groupname']) and count($_SESSION['ReportList']['groupname']) > 0) { // then there are reports to show, show by grouping
263				foreach ($_SESSION['ReportList'] as $Report) {
264					if (isset($Report['groupname']) and $Report['groupname'] == $GroupID and $Report['defaultreport'] == $Def) {
265						$RptLinks.= '<li class="menu_group_item">';
266						$RptLinks.= '<p><a href="' . $RootPath . '/reportwriter/ReportMaker.php?action=go&amp;reportid=';
267						$RptLinks.= urlencode($Report['id']) . '">&nbsp; ' . __($Report['reportname']) . '</a></p>';
268						$RptLinks.= '</li>';
269						$NoEntries = false;
270					}
271				}
272				// now fetch the form groups that are a part of this group (List after reports)
273				$NoForms = true;
274				foreach ($_SESSION['ReportList'] as $Report) {
275					$Group = explode(':', $Report['groupname']); // break into main group and form group array
276					if ($NoForms and $Group[0] == $GroupID and $Report['reporttype'] == 'frm' and $Report['defaultreport'] == $Def) {
277						$RptLinks.= '<li class="menu_group_item">';
278						$RptLinks.= '<img src="' . $RootPath . '/css/' . $_SESSION['Theme'] . '/images/folders.gif" width="16" height="13" alt="" />&nbsp; ';
279						$RptLinks.= '<p><a href="' . $RootPath . '/reportwriter/FormMaker.php?id=' . urlencode($Report['groupname']) . '">';
280						$RptLinks.= $_SESSION['FormGroups'][$Report['groupname']] . '</a></p>';
281						$RptLinks.= '</li>';
282						$NoForms = false;
283						$NoEntries = false;
284					}
285				}
286			}
287			if ($NoEntries) $RptLinks.= '<li class="menu_group_item">' . __('There are no reports to show!') . '</li>';
288		}
289		return $RptLinks;
290	}
