460	
461	function locale_number_format($Number, $DecimalPlaces = 0) {
462		global $DecimalPoint;
463		global $ThousandsSeparator;
464		if ($DecimalPlaces == null) $DecimalPlaces = 0;
465		if (substr($_SESSION['Language'], 3, 2) == 'IN') { // If country is India (??_IN.utf8). See Indian Numbering System in Manual, Multilanguage, Technical Overview.
466			return indian_number_format(floatval($Number), $DecimalPlaces);
467		} else {
468			if (!is_numeric($DecimalPlaces) and $DecimalPlaces == 'Variable') {
469				$DecimalPlaces = mb_strlen($Number) - mb_strlen(intval($Number));
470				if ($DecimalPlaces > 0) {
471					$DecimalPlaces--;
472				}
473			}
474			return number_format(floatval($Number), $DecimalPlaces, $DecimalPoint, $ThousandsSeparator);
475		}
476	}
