478	/* and to parse the input of the user into useable number */
479	
480	function filter_number_format($Number) {
481		global $DecimalPoint;
482		global $ThousandsSeparator;
483		$SQLFormatNumber = str_replace($DecimalPoint, '.', str_replace($ThousandsSeparator, '', trim($Number)));
484		/*It is possible if the user entered the $DecimalPoint as a thousands separator and the $DecimalPoint is a comma that the result of this could contain several periods "." so need to ditch all but the last "." */
485		if (mb_substr_count($SQLFormatNumber, '.') > 1) {
486			return str_replace('.', '', mb_substr($SQLFormatNumber, 0, mb_strrpos($SQLFormatNumber, '.'))) . mb_substr($SQLFormatNumber, mb_strrpos($SQLFormatNumber, '.'));
487	
488			echo '<br /> Number of periods: ' . $NumberOfPeriods . ' $SQLFormatNumber = ' . $SQLFormatNumber;
489	
490		} else {
491			return $SQLFormatNumber;
492		}
493	}
