495	function indian_number_format($Number, $DecimalPlaces) {
496		$IntegerNumber = intval($Number);
497		$DecimalValue = $Number - $IntegerNumber;
498		if ($DecimalPlaces != 'Variable') {
499			$DecimalValue = round($DecimalValue, $DecimalPlaces);
500		}
